int main() {
    int h, w;
    while (scanf("%d %d", &h, &w) == 2 && h != 0 && w != 0) {
        int grid[100][100];
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                scanf("%d", &grid[i][j]);
            }
        }

        int max_capacity = 0;

        for (int r1 = 0; r1 < h; r1++) {
            for (int c1 = 0; c1 < w; c1++) {
                for (int r2 = r1 + 2; r2 < h; r2++) {
                    for (int c2 = c1 + 2; c2 < w; c2++) {
                        int min_border = INT_MAX;
                        int max_inner = INT_MIN;

                        // top and bottom borders
                        for (int c = c1; c <= c2; c++) {
                            if (grid[r1][c] < min_border) min_border = grid[r1][c];
                            if (grid[r2][c] < min_border) min_border = grid[r2][c];
                        }
                        // left and right borders
                        for (int r = r1 + 1; r <= r2 - 1; r++) {
                            if (grid[r][c1] < min_border) min_border = grid[r][c1];
                            if (grid[r][c2] < min_border) min_border = grid[r][c2];
                        }

                        // inner cells
                        for (int r = r1 + 1; r <= r2 - 1; r++) {
                            for (int c = c1 + 1; c <= c2 - 1; c++) {
                                if (grid[r][c] > max_inner) max_inner = grid[r][c];
                            }
                        }

                        if (min_border > max_inner) {
                            int capacity = 0;
                            for (int r = r1 + 1; r <= r2 - 1; r++) {
                                for (int c = c1 + 1; c <= c2 - 1; c++) {
                                    capacity += min_border - grid[r][c];
                                }
                            }
                            if (capacity > max_capacity) max_capacity = capacity;
                        }
                    }
                }
            }
        }

        printf("%d\n", max_capacity);
    }
    return 0;
}

