typedef long long ll;

static ll maxll(ll a, ll b) { return a > b ? a : b; }
static ll minll(ll a, ll b) { return a < b ? a : b; }

int main(void) {
    int H, W;

    while (scanf("%d %d", &H, &W) == 2) {
        if (H == 0 && W == 0) break;

        int **a = (int **)malloc(H * sizeof(int *));
        for (int i = 0; i < H; i++) {
            a[i] = (int *)malloc(W * sizeof(int));
            for (int j = 0; j < W; j++) scanf("%d", &a[i][j]);
        }

        /* prefix sums of heights */
        ll **ps = (ll **)malloc((H + 1) * sizeof(ll *));
        for (int i = 0; i <= H; i++) {
            ps[i] = (ll *)calloc(W + 1, sizeof(ll));
        }

        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                ps[i + 1][j + 1] = ps[i][j + 1] + ps[i + 1][j] - ps[i][j] + a[i][j];
            }
        }

        ll ans = 0;

        /* Enumerate outer rectangle [r1..r2][c1..c2], must have inner area */
        for (int r1 = 0; r1 < H; r1++) {
            for (int r2 = r1 + 2; r2 < H; r2++) {
                for (int c1 = 0; c1 < W; c1++) {
                    for (int c2 = c1 + 2; c2 < W; c2++) {
                        int borderMin = 1 << 30;

                        for (int c = c1; c <= c2; c++) {
                            if (a[r1][c] < borderMin) borderMin = a[r1][c];
                            if (a[r2][c] < borderMin) borderMin = a[r2][c];
                        }
                        for (int r = r1 + 1; r < r2; r++) {
                            if (a[r][c1] < borderMin) borderMin = a[r][c1];
                            if (a[r][c2] < borderMin) borderMin = a[r][c2];
                        }

                        int ok = 1;
                        int innerMax = -1 << 30;
                        for (int r = r1 + 1; r < r2 && ok; r++) {
                            for (int c = c1 + 1; c < c2; c++) {
                                if (a[r][c] >= borderMin) {
                                    ok = 0;
                                    break;
                                }
                                if (a[r][c] > innerMax) innerMax = a[r][c];
                            }
                        }
                        if (!ok) continue;

                        int waterLevel = borderMin;

                        int ih = r2 - r1 - 1;
                        int iw = c2 - c1 - 1;
                        ll innerSum = ps[r2][c2] - ps[r1 + 1][c2] - ps[r2][c1 + 1] + ps[r1 + 1][c1 + 1];
                        ll area = (ll)ih * iw;
                        ll capacity = area * waterLevel - innerSum;
                        ans = maxll(ans, capacity);
                    }
                }
            }
        }

        printf("%lld\n", ans);

        for (int i = 0; i < H; i++) free(a[i]);
        free(a);
        for (int i = 0; i <= H; i++) free(ps[i]);
        free(ps);
    }

    return 0;
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int H = sc.nextInt();
            int W = sc.nextInt();
            if (H == 0 && W == 0) break;

            int[][] grid = new int[H][W];
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    grid[i][j] = sc.nextInt();
                }
            }

            int maxCapacity = 0;

            // Try all possible top-left and bottom-right corners
            for (int r1 = 0; r1 < H; r1++) {
                for (int c1 = 0; c1 < W; c1++) {
                    for (int r2 = r1 + 2; r2 < H; r2++) {
                        for (int c2 = c1 + 2; c2 < W; c2++) {
                            // Check if border is higher than all inner cells
                            int minBorder = Integer.MAX_VALUE;
                            boolean valid = true;

                            // Top and bottom rows
                            for (int c = c1; c <= c2; c++) {
                                minBorder = Math.min(minBorder, grid[r1][c]);
                                minBorder = Math.min(minBorder, grid[r2][c]);
                            }
                            // Left and right columns (excluding corners already counted)
                            for (int r = r1 + 1; r <= r2 - 1; r++) {
                                minBorder = Math.min(minBorder, grid[r][c1]);
                                minBorder = Math.min(minBorder, grid[r][c2]);
                            }

                            // Check all inner cells are strictly lower than minBorder
                            for (int r = r1 + 1; r < r2 && valid; r++) {
                                for (int c = c1 + 1; c < c2 && valid; c++) {
                                    if (grid[r][c] >= minBorder) {
                                        valid = false;
                                    }
                                }
                            }

                            if (valid) {
                                int capacity = 0;
                                for (int r = r1 + 1; r < r2; r++) {
                                    for (int c = c1 + 1; c < c2; c++) {
                                        capacity += minBorder - grid[r][c];
                                    }
                                }
                                maxCapacity = Math.max(maxCapacity, capacity);
                            }
                        }
                    }
                }
            }

            System.out.println(maxCapacity);
        }
        sc.close();
    }
}

