            long[][] ps = new long[H+1][W+1];
            for (int i = 0; i < H; i++)
                for (int j = 0; j < W; j++)
                    ps[i+1][j+1] = g[i][j] + ps[i][j+1] + ps[i+1][j] - ps[i][j];

            // row min: rowMin[r][c1][c2]
            int[][][] rowMin = new int[H][W][W];
            for (int r = 0; r < H; r++)
                for (int c1 = 0; c1 < W; c1++) { rowMin[r][c1][c1]=g[r][c1]; for(int c2=c1+1;c2<W;c2++) rowMin[r][c1][c2]=Math.min(rowMin[r][c1][c2-1],g[r][c2]); }
            int[][][] colMin = new int[W][H][H];
            for (int c = 0; c < W; c++)
                for (int r1 = 0; r1 < H; r1++) { colMin[c][r1][r1]=g[r1][c]; for(int r2=r1+1;r2<H;r2++) colMin[c][r1][r2]=Math.min(colMin[c][r1][r2-1],g[r2][c]); }
            // 2D range max
            // simple O(n^2m^2) for small grids
            long ans = 0;
            for (int r1=0;r1<H;r1++) for (int r2=r1+2;r2<H;r2++) for (int c1=0;c1<W;c1++) for (int c2=c1+2;c2<W;c2++) {
                int bmin=Math.min(Math.min(rowMin[r1][c1][c2],rowMin[r2][c1][c2]),Math.min(colMin[c1][r1][r2],colMin[c2][r1][r2]));
                int imax=Integer.MIN_VALUE;
                for(int r=r1+1;r<r2;r++) for(int c=c1+1;c<c2;c++) imax=Math.max(imax,g[r][c]);
                if(bmin>imax) {
                    long s=ps[r2][c2]-ps[r1+1][c2]-ps[r2][c1+1]+ps[r1+1][c1+1];
                    long cap=(long)(r2-r1-1)*(c2-c1-1)*bmin-s;
                    ans=Math.max(ans,cap);
                }
            }
            System.out.println(ans);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return Integer.MIN_VALUE;
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            int n = fs.nextInt();
            if (n == Integer.MIN_VALUE) break;
            int m = fs.nextInt();
            if (n == 0 && m == 0) break;

            int[][] a = new int[n][m];
            int maxH = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    a[i][j] = fs.nextInt();
                    if (a[i][j] > maxH) maxH = a[i][j];
                }
            }

            long answer = 0;

            // Try every possible water level h.
            // Cells with height < h are inside candidates.
            // A valid pond rectangle at level h must have:
            // - all inner cells < h
            // - all border cells >= h
            //
            // For each h, build a binary matrix low[i][j] = (a[i][j] < h).
            // Then enumerate top/bottom rows and find column intervals where:
            //   top and bottom rows are all high on the interval,
            //   interior rows (if any) are low on interior columns,
            //   left/right border columns are high for all rows in [top..bottom].
            //
            // Capacity = sum over inner cells of (h - a[i][j]).
            //
            // Constraints are not provided in the statement here, so we use
            // an O(H * n^2 * m) style solution with prefix sums, which is
            // acceptable for typical contest limits of this classic problem.
            for (int h = 1; h <= maxH; h++) {
                int[][] lowPrefCol = new int[n + 1][m];
                int[][] highPrefCol = new int[n + 1][m];
                long[][] waterPref = new long[n + 1][m + 1];

                for (int i = 0; i < n; i++) {
                    long rowSum = 0;
                    for (int j = 0; j < m; j++) {
                        int low = a[i][j] < h ? 1 : 0;
                        int high = a[i][j] >= h ? 1 : 0;
                        lowPrefCol[i + 1][j] = lowPrefCol[i][j] + low;
                        highPrefCol[i + 1][j] = highPrefCol[i][j] + high;

                        long w = a[i][j] < h ? (h - a[i][j]) : 0;
                        rowSum += w;
                        waterPref[i + 1][j + 1] = waterPref[i][j + 1] + rowSum;
                    }
                }

                for (int top = 0; top < n; top++) {
                    for (int bottom = top + 2; bottom < n; bottom++) {
                        int innerRows = bottom - top - 1;

                        int start = -1;
                        for (int col = 0; col < m; col++) {
                            boolean topHigh = a[top][col] >= h;
                            boolean bottomHigh = a[bottom][col] >= h;
                            boolean verticalHigh = (highPrefCol[bottom + 1][col] - highPrefCol[top][col] == bottom - top + 1);
                            boolean innerAllLow = (lowPrefCol[bottom][col] - lowPrefCol[top + 1][col] == innerRows);

                            // Column can be used as side border if all cells on it are high.
                            boolean canBeSide = verticalHigh;

                            // Column can be used as interior if top/bottom are high and all inner are low.
                            boolean canBeInterior = topHigh && bottomHigh && innerAllLow;

                            if (start == -1) {
                                if (canBeSide) start = col;
                            } else {
                                if (canBeInterior) {
                                    // continue
                                } else if (canBeSide) {
                                    // rectangle [start..col] valid if width >= 3
                                    if (col - start + 1 >= 3) {
                                        int left = start;
                                        int right = col;
                                        long cap = rectSum(waterPref, top + 1, left + 1, bottom - 1, right - 1);
                                        if (cap > answer) answer = cap;
                                    }
                                    start = col;
                                } else {
                                    start = -1;
                                }
                            }
                        }
                    }
                }
            }

            out.append(answer).append('\n');
        }

        System.out.print(out.toString());
    }

    static long rectSum(long[][] pref, int r1, int c1, int r2, int c2) {
        if (r1 > r2 || c1 > c2) return 0;
        return pref[r2 + 1][c2 + 1] - pref[r1][c2 + 1] - pref[r2 + 1][c1] + pref[r1][c1];
    }
}

