            ps[i+1][j+1] = g[i][j] + ps[i][j+1] + ps[i+1][j] - ps[i][j];

        auto rectSum = [&](int r1,int c1,int r2,int c2) -> long long {
            return ps[r2+1][c2+1] - ps[r1][c2+1] - ps[r2+1][c1] + ps[r1][c1];
        };

        long long ans = 0;
        for(int r1=0;r1<N;r1++) for(int r2=r1+2;r2<N;r2++)
        for(int c1=0;c1<M;c1++) for(int c2=c1+2;c2<M;c2++){
            // border min
            int bmin = INT_MAX;
            for(int j=c1;j<=c2;j++) bmin=min(bmin,min(g[r1][j],g[r2][j]));
            for(int i=r1+1;i<r2;i++) bmin=min(bmin,min(g[i][c1],g[i][c2]));
            // inner max
            int imax = INT_MIN;
            for(int i=r1+1;i<r2;i++) for(int j=c1+1;j<c2;j++) imax=max(imax,g[i][j]);
            if(bmin > imax){
                long long isum = rectSum(r1+1,c1+1,r2-1,c2-1);
                long long cnt = (long long)(r2-r1-1)*(c2-c1-1);
                ans = max(ans, (long long)bmin*cnt - isum);
            }
        }
        cout << ans << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;

/*
We need the maximum capacity of a rectangular pond in a grid of elevations.

For a chosen rectangle:
- border cells are the wall
- inner cells are the pond bottom
- every border cell must be strictly higher than every inner cell

If wall height = min(border), and bottom must be below it, then the maximum
water depth over an inner cell of height h is (wall - h). Thus capacity is

    sum_{inner cells}(min(border) - h)

provided max(inner) < min(border).

So for every rectangle with at least size 3x3:
    capacity = inner_area * min(border) - sum(inner)

We must maximize this.

Key optimization:
Fix top row t and bottom row b. Then for each column c:
- vertical border minimum on rows [t..b] at column c
- inner-column sum on rows [t+1..b-1] at column c
- inner-column maximum on rows [t+1..b-1] at column c

For a rectangle [l..r]:
- border minimum is minimum of:
    * top row values on l..r
    * bottom row values on l..r
    * vertical border mins at columns l and r
- inner sum is sum of inner-column sums on columns l+1..r-1
- inner max is max of inner-column max on columns l+1..r-1

Then:
capacity = (r-l-1)*(b-t-1) * border_min - inner_sum
valid iff inner_max < border_min

For each pair (t,b), we scan all l,r. Constraints are not provided, so we use
an O(R^2 * C^2) approach with O(1) range queries by sparse tables/prefix sums,
which is typically acceptable for moderate grid sizes.
*/

struct SparseMin {
    int n;
    vector<int> lg;
    vector<vector<int>> st;
    void build(const vector<int>& a) {
        n = (int)a.size();
        lg.assign(n + 1, 0);
        for (int i = 2; i <= n; ++i) lg[i] = lg[i / 2] + 1;
        int K = lg[n] + 1;
        st.assign(K, vector<int>(n));
        st[0] = a;
        for (int k = 1; k < K; ++k) {
            int len = 1 << k;
            int half = len >> 1;
            for (int i = 0; i + len <= n; ++i) {
                st[k][i] = min(st[k - 1][i], st[k - 1][i + half]);
            }
        }
    }
    int query(int l, int r) const {
        if (l > r) return INT_MAX;
        int k = lg[r - l + 1];
        return min(st[k][l], st[k][r - (1 << k) + 1]);
    }
};

struct SparseMax {
    int n;
    vector<int> lg;
    vector<vector<int>> st;
    void build(const vector<int>& a) {
        n = (int)a.size();
        lg.assign(n + 1, 0);
        for (int i = 2; i <= n; ++i) lg[i] = lg[i / 2] + 1;
        int K = lg[n] + 1;
        st.assign(K, vector<int>(n));
        st[0] = a;
        for (int k = 1; k < K; ++k) {
            int len = 1 << k;
            int half = len >> 1;
            for (int i = 0; i + len <= n; ++i) {
                st[k][i] = max(st[k - 1][i], st[k - 1][i + half]);
            }
        }
    }
    int query(int l, int r) const {
        if (l > r) return INT_MIN;
        int k = lg[r - l + 1];
        return max(st[k][l], st[k][r - (1 << k) + 1]);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int R, C;
    while (cin >> R >> C) {
        if (!cin) break;
        vector<vector<int>> a(R, vector<int>(C));
        for (int i = 0; i < R; ++i)
            for (int j = 0; j < C; ++j)
                cin >> a[i][j];

        long long ans = 0;

        if (R >= 3 && C >= 3) {
            // For each row, sparse table for min on intervals.
            vector<SparseMin> rowMin(R);
            for (int i = 0; i < R; ++i) rowMin[i].build(a[i]);

            // Fix top and bottom rows.
            for (int t = 0; t < R; ++t) {
                vector<int> vertMin(C, a[t][0]);
                for (int c = 0; c < C; ++c) vertMin[c] = a[t][c];

                vector<long long> innerColSum(C, 0);
                vector<int> innerColMax(C, INT_MIN);

                for (int b = t + 2; b < R; ++b) {
                    int midRow = b - 1;
                    for (int c = 0; c < C; ++c) {
                        vertMin[c] = min(vertMin[c], a[b][c]);
                        innerColSum[c] += a[midRow][c];
                        innerColMax[c] = max(innerColMax[c], a[midRow][c]);
                    }

                    // Prefix sums of inner-column sums.
                    vector<long long> pref(C + 1, 0);
                    for (int c = 0; c < C; ++c) pref[c + 1] = pref[c] + innerColSum[c];

                    SparseMax stInnerMax;
                    stInnerMax.build(innerColMax);

                    int innerHeight = b - t - 1;

                    for (int l = 0; l + 2 < C; ++l) {
                        for (int r = l + 2; r < C; ++r) {
                            int borderMin = min({
                                rowMin[t].query(l, r),
                                rowMin[b].query(l, r),
                                vertMin[l],
                                vertMin[r]
                            });

                            int mxInner = stInnerMax.query(l + 1, r - 1);
                            if (mxInner >= borderMin) continue;

                            long long sumInner = pref[r] - pref[l + 1];
                            long long innerWidth = r - l - 1;
                            long long area = innerWidth * innerHeight;
                            long long cap = area * 1LL * borderMin - sumInner;
                            ans = max(ans, cap);
                        }
                    }
                }
            }
        }

        cout << ans << "\n";
    }

    return 0;
}

