import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    out = []

    while True:
        try:
            h = int(next(it))
            w = int(next(it))
        except StopIteration:
            break

        if h == 0 and w == 0:
            break

        a = [[int(next(it)) for _ in range(w)] for _ in range(h)]

        # Prefix sums for fast rectangle sum queries
        ps = [[0] * (w + 1) for _ in range(h + 1)]
        for i in range(h):
            row_sum = 0
            for j in range(w):
                row_sum += a[i][j]
                ps[i + 1][j + 1] = ps[i][j + 1] + row_sum

        def rect_sum(r1, c1, r2, c2):
            # inclusive rectangle
            return ps[r2 + 1][c2 + 1] - ps[r1][c2 + 1] - ps[r2 + 1][c1] + ps[r1][c1]

        ans = 0

        # Enumerate pond rectangles with at least 3x3 size
        # Border cells must all be strictly higher than all inner cells.
        # Water level is min(border), capacity = sum(level - inner_cell).
        for top in range(h - 2):
            for bottom in range(top + 2, h):
                for left in range(w - 2):
                    for right in range(left + 2, w):
                        border_min = 10**18
                        inner_max = -10**18

                        # top and bottom borders
                        for c in range(left, right + 1):
                            if a[top][c] < border_min:
                                border_min = a[top][c]
                            if a[bottom][c] < border_min:
                                border_min = a[bottom][c]

                        # left and right borders excluding corners already counted
                        for r in range(top + 1, bottom):
                            if a[r][left] < border_min:
                                border_min = a[r][left]
                            if a[r][right] < border_min:
                                border_min = a[r][right]

                        # check inner cells and find max
                        valid = True
                        for r in range(top + 1, bottom):
                            for c in range(left + 1, right):
                                if a[r][c] >= border_min:
                                    valid = False
                                    break
                                if a[r][c] > inner_max:
                                    inner_max = a[r][c]
                            if not valid:
                                break

                        if not valid:
                            continue

                        inner_area = (bottom - top - 1) * (right - left - 1)
                        inner_total = rect_sum(top + 1, left + 1, bottom - 1, right - 1)
                        capacity = border_min * inner_area - inner_total
                        if capacity > ans:
                            ans = capacity

        out.append(str(ans))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
